struct node *bstInsert(struct node *tree, int val) {
    if (tree == NULL) {
        return newNode(val);
    } else if (val < tree->value) {
        tree->left = bstInsert(tree->left, val);
    } else if (val > tree->value) {
        tree->right = bstInsert(tree->right, val);
    }
