bool bstSearch(struct node *tree, int val) {
    if (tree == NULL) {
        return false;
    } else if (val < tree->value) {
        return bstSearch(tree->left, val);
    } else if (val > tree->value) {
        return bstSearch(tree->right, val);
    } else {  // (val == tree->value)
        return true;
    }
}

struct node *bstDelete(struct node *tree, int val) {
    if (tree == NULL) {
        return tree;
    } else if (val < tree->value) {
        tree->left = bstDelete(tree->left, val);
    } else if (val > tree->value) {
        tree->right = bstDelete(tree->right, val);
    } else {
        struct node *new;
        if (tree->left == NULL) {
            new = tree->right;
        } else if (tree->right == NULL) {
            new = tree->left;
        } else {
            new = bstJoin(tree->left, tree->right);
        }
        free(tree);
        tree = new;
    }
    return tree;
}

static struct node *bstJoin(struct node *t1, struct node *t2) {
    if (t1 == NULL) {
        return t2;
    }

    if (t2 == NULL) {
        return t1;
    }

    struct node *curr = t2;
    struct node *parent = NULL;
    while (curr->left != NULL) {
        parent = curr;
        curr = curr->left;
    }

    if (parent != NULL) {
        parent->left = curr->right;
        curr->right = t2;
    }
    curr->left = t1;
    return curr;
}

