avlInsert(t, v):
    Input:  AVL tree t, item v
    Output: t with v inserted

    if t is empty:
        return new node containing v
    else if v < t->item:
        t->left = avlInsert(t->left, v)
    else if v > t->item:
        t->right = avlInsert(t->right, v)
    else:
        return t
    return avlRebalance(t)

avlRebalance(t):
    Input:  possibly unbalanced tree t
    Output: balanced t

    bal = balance(t)
    if bal > 1:
        if balance(t->left) < 0:
            t->left = rotateLeft(t->left)
        t = rotateRight(t)
    else if bal < -1:
        if balance(t->right) > 0:
            t->right = rotateRight(t->right)
        t = rotateLeft(t)
    return t

balance(t):
    Input:  tree t
    Output: balance factor of t

    return height(t->left) - height(t->right)

avlDelete(t, v):
    Input:  AVL tree t, item v
    Output: t with v deleted

    if t is empty:
        return empty tree
    else if v < t->item:
        t->left = avlDelete(t->left, v)
    else if v > t->item:
        t->right = avlDelete(t->right, v)
    else:
        if t->left is empty:
            temp = t->right
            free(t)
            return temp
        else if t->right is empty:
            temp = t->left
            free(t)
            return temp
        else:
            successor = minimum value in t->right
            t->item = successor
            t->right = avlDelete(t->right, successor)

    return avlRebalance(t)

avlInsert(t, v):
    Input:  AVL tree t, item v
    Output: t with v inserted

    if t is empty:
        return new node containing v
    else if v < t->item:
        t->left = avlInsert(t->left, v)
    else if v > t->item:
        t->right = avlInsert(t->right, v)
    else:
        return t
    return avlRebalance(t)

avlRebalance(t):
    Input:  possibly unbalanced tree t
    Output: balanced t

    bal = balance(t)
    if bal > 1:
        if balance(t->left) < 0:
            t->left = rotateLeft(t->left)
        t = rotateRight(t)
    else if bal < -1:
        if balance(t->right) > 0:
            t->right = rotateRight(t->right)
        t = rotateLeft(t)
    return t

