/* Supplemental implementation - NOT 26T2 manual or 25T3 lecture source.
 * The attached manual gives insertion, deletion and rebalancing for AVL
 * trees as pseudocode only, and prints no AVL search in any form. This body
 * is supplied by this application so that the AVL search descent can be
 * executed and compared, statement for statement, with the bstSearch the
 * manual does print (pp. 11-14). It is the same code as the "AVL search"
 * study conversion registered in assets/manual-boundary-data.js.
 *
 * It reads no height field and performs no rotation, because the AVL
 * invariant constrains the SHAPE of the tree and not its ORDER.
 */
bool avlSearch(struct node *t, int v) {
    if (t == NULL) return false;
    if (v < t->item) return avlSearch(t->left, v);
    if (v > t->item) return avlSearch(t->right, v);
    return true;
}

typedef struct hashTable *HashTable;

HashTable HashTableNew(void);
void HashTableFree(HashTable ht);
void HashTableInsert(HashTable ht, int key, int value);
void HashTableDelete(HashTable ht, int key);
bool HashTableContains(HashTable ht, int key);
int HashTableGet(HashTable ht, int key);
int HashTableSize(HashTable ht);

#define INITIAL_NUM_SLOTS 11
#define MAX_LOAD_FACTOR 2.0

struct hashTable {
    struct node **slots;
    int numSlots;
    int numItems;
};

struct node {
    int key;
    int value;
    struct node *next;
};

static void freeList(struct node *list);
static struct node *doInsert(HashTable ht, struct node *list,
                             int key, int value);
static struct node *newNode(int key, int value);
static struct node *doDelete(HashTable ht, struct node *list, int key);
static inline unsigned int hash(int key, int N);

HashTable HashTableNew(void) {
    HashTable ht = malloc(sizeof(*ht));
    if (ht == NULL) {
        fprintf(stderr, "error: out of memory\n");
        exit(EXIT_FAILURE);
    }

    ht->slots = calloc(INITIAL_NUM_SLOTS, sizeof(struct node *));
    ht->numSlots = INITIAL_NUM_SLOTS;
    ht->numItems = 0;
    return ht;
}

void HashTableFree(HashTable ht) {
    for (int i = 0; i < ht->numSlots; i++) {
        freeList(ht->slots[i]);
    }
    free(ht->slots);
    free(ht);
}

static void freeList(struct node *list) {
    struct node *curr = list;
    while (curr != NULL) {
        struct node *temp = curr;
        curr = curr->next;
        free(temp);
    }
}

void HashTableInsert(HashTable ht, int key, int value) {
    if (ht->numItems >= MAX_LOAD_FACTOR * ht->numSlots) {
        printf("warning: resize not implemented!\n");
    }

    int i = hash(key, ht->numSlots);
    ht->slots[i] = doInsert(ht, ht->slots[i], key, value);
}

static struct node *doInsert(HashTable ht, struct node *list,
                             int key, int value) {
    if (list == NULL) {
        ht->numItems++;
        return newNode(key, value);
    } else if (list->key == key) {
        list->value = value;
        return list;
    } else {
        list->next = doInsert(ht, list->next, key, value);
        return list;
    }
}

static struct node *newNode(int key, int value) {
    struct node *new = malloc(sizeof(struct node));
    if (new == NULL) {
        fprintf(stderr, "error: out of memory\n");
        exit(EXIT_FAILURE);
    }

    new->key = key;
    new->value = value;
    new->next = NULL;
    return new;
}

void HashTableDelete(HashTable ht, int key) {
    int i = hash(key, ht->numSlots);
    ht->slots[i] = doDelete(ht, ht->slots[i], key);
}

static struct node *doDelete(HashTable ht, struct node *list, int key) {
    if (list == NULL) {
        return NULL;
    } else if (list->key == key) {
        ht->numItems--;
        struct node *newHead = list->next;
        free(list);
        return newHead;
    } else {
        list->next = doDelete(ht, list->next, key);
        return list;
    }
}

bool HashTableContains(HashTable ht, int key) {
    int i = hash(key, ht->numSlots);
    struct node *curr;
    for (curr = ht->slots[i]; curr != NULL; curr = curr->next) {
        if (curr->key == key) {
            return true;
        }
    }
    return false;
}

int HashTableGet(HashTable ht, int key) {
    int i = hash(key, ht->numSlots);
    struct node *curr;
    for (curr = ht->slots[i]; curr != NULL; curr = curr->next) {
        if (curr->key == key) {
            return curr->value;
        }
    }
    printf("error: key %d does not exist!\n", key);
    return -1;
}

int HashTableSize(HashTable ht) {
    return ht->numItems;
}

static inline unsigned int hash(int key, int N) {
    const unsigned int magic = 0x45d9f3b;
    unsigned int h = 1U + INT_MAX;
    h += key;
    h = ((h >> 16) ^ h) * magic;
    h = ((h >> 16) ^ h) * magic;
    h = (h >> 16) ^ h;
    return h % N;
}

/* SUPPLEMENTAL C - not 26T2 manual source and not 25T3 lecture source.
   The manual's HashTableInsert reaches
       printf("warning: resize not implemented!");
   and then inserts into the unchanged table. This block is that branch,
   completed. Every policy choice it makes is declared here:

     Growth    double the slot count, then round up to the next prime, so the
               modulus keeps mixing keys.  11 -> 23 -> 47 -> 97 -> 193 -> 389.
     Trigger   the load factor numItems / numSlots. MAX_LOAD_FACTOR is the
               manual's own constant; DEMO_LOAD_FACTOR exists only so that the
               rehash is visible in a short trace. The threshold is a policy
               choice, and the tracer names which one is in force. The rehash
               itself is not a choice: it is required for correctness.
     Ownership the new slot array is allocated BEFORE anything moves, so a
               failed allocation leaves the old table usable. Existing nodes
               are MOVED by relinking ->next, never copied, so no key/value
               pair is duplicated and no node is freed twice. Only the old
               slot array is freed. */

#define DEMO_LOAD_FACTOR 0.25

static const int RESIZE_PRIMES[] = {11, 23, 47, 97, 193, 389};
#define NUM_RESIZE_PRIMES 6

static int nextNumSlots(int numSlots) {
    for (int i = 0; i < NUM_RESIZE_PRIMES; i++) {
        if (RESIZE_PRIMES[i] >= 2 * numSlots) {
            return RESIZE_PRIMES[i];
        }
    }
    return 2 * numSlots + 1;
}

static void HashTableResize(HashTable ht) {
    int oldNumSlots = ht->numSlots;
    struct node **oldSlots = ht->slots;
    int newNumSlots = nextNumSlots(oldNumSlots);

    struct node **newSlots = calloc(newNumSlots, sizeof(struct node *));
    if (newSlots == NULL) {
        fprintf(stderr, "error: out of memory\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < oldNumSlots; i++) {
        struct node *curr = oldSlots[i];
        while (curr != NULL) {
            struct node *next = curr->next;
            unsigned int j = hash(curr->key, newNumSlots);
            curr->next = newSlots[j];
            newSlots[j] = curr;
            curr = next;
        }
    }

    free(oldSlots);
    ht->slots = newSlots;
    ht->numSlots = newNumSlots;
}

void HashTableInsertResizing(HashTable ht, int key, int value, double maxLoad) {
    if (ht->numItems >= maxLoad * ht->numSlots) {
        HashTableResize(ht);
    }

    int i = hash(key, ht->numSlots);
    ht->slots[i] = doInsert(ht, ht->slots[i], key, value);
}

typedef struct pq *Pq;

Pq PqNew(void);
void PqFree(Pq pq);
void PqInsert(Pq pq, int item, int priority);
int PqDelete(Pq pq);
int PqPeek(Pq pq);

#define INITIAL_CAPACITY 8

struct pq {
    struct pqItem *items;
    int numItems;
    int capacity;
};

struct pqItem {
    int item;
    int priority;
};

static void resize(Pq pq);
static void fixUp(struct pqItem *items, int i);
static void swap(struct pqItem *items, int i, int j);
static void fixDown(struct pqItem *items, int i, int N);

Pq PqNew(void) {
    Pq pq = malloc(sizeof(struct pq));
    if (pq == NULL) {
        fprintf(stderr, "error: out of memory\n");
        exit(EXIT_FAILURE);
    }

    pq->numItems = 0;
    pq->capacity = INITIAL_CAPACITY;
    pq->items = malloc((pq->capacity + 1) * sizeof(struct pqItem));
    return pq;
}

void PqFree(Pq pq) {
    free(pq->items);
    free(pq);
}

void PqInsert(Pq pq, int item, int priority) {
    if (pq->numItems == pq->capacity) {
        resize(pq);
    }

    pq->numItems++;
    pq->items[pq->numItems] = (struct pqItem){
        .item = item,
        .priority = priority,
    };
    fixUp(pq->items, pq->numItems);
}

static void resize(Pq pq) {
    pq->capacity *= 2;
    pq->items = realloc(pq->items, (pq->capacity + 1) * sizeof(struct pqItem));
    if (pq->items == NULL) {
        fprintf(stderr, "error: out of memory\n");
        exit(EXIT_FAILURE);
    }
}

static void fixUp(struct pqItem *items, int i) {
    while (i > 1 && items[i].priority > items[i / 2].priority) {
        swap(items, i, i / 2);
        i = i / 2;
    }
}

static void swap(struct pqItem *items, int i, int j) {
    struct pqItem tmp = items[i];
    items[i] = items[j];
    items[j] = tmp;
}

int PqDelete(Pq pq) {
    if (pq->numItems == 0) {
        fprintf(stderr, "error: pq is empty\n");
        exit(EXIT_FAILURE);
    }

    int item = pq->items[1].item;
    pq->items[1] = pq->items[pq->numItems];
    pq->numItems--;
    fixDown(pq->items, 1, pq->numItems);
    return item;
}

static void fixDown(struct pqItem *items, int i, int N) {
    while (2 * i <= N) {
        int j = 2 * i;
        if (j < N && items[j + 1].priority > items[j].priority) {
            j++;
        }
        if (items[i].priority >= items[j].priority) {
            break;
        }
        swap(items, i, j);
        i = j;
    }
}

int PqPeek(Pq pq) {
    if (pq->numItems == 0) {
        fprintf(stderr, "error: pq is empty\n");
        exit(EXIT_FAILURE);
    }

    return pq->items[1].item;
}

#define ALPHABET_SIZE 26

typedef struct node *Trie;

struct node {
    struct node *children[ALPHABET_SIZE];
    bool finish;
};

static Trie doTrieDelete(Trie t, char *key, bool isRoot);

Trie trieNew(void) {
    Trie t = calloc(1, sizeof(*t));
    if (t == NULL) {
        fprintf(stderr, "error: out of memory\n");
        exit(EXIT_FAILURE);
    }
    return t;
}

void trieFree(Trie t) {
    if (t == NULL) {
        return;
    }

    for (int i = 0; i < ALPHABET_SIZE; i++) {
        trieFree(t->children[i]);
    }
    free(t);
}

Trie trieInsert(Trie t, char *key) {
    if (t == NULL) {
        t = calloc(1, sizeof(*t));
    }

    if (key[0] == '\0') {
        t->finish = true;
        return t;
    }

    int i = key[0] - 'a';
    t->children[i] = trieInsert(t->children[i], &key[1]);
    return t;
}

bool trieSearch(Trie t, char *key) {
    if (t == NULL) {
        return false;
    }

    if (key[0] == '\0') {
        return t->finish;
    }

    char first = key[0];
    int i = first - 'a';
    return trieSearch(t->children[i], &key[1]);
}

Trie trieDelete(Trie t, char *key) {
    return doTrieDelete(t, key, true);
}

static Trie doTrieDelete(Trie t, char *key, bool isRoot) {
    if (t == NULL) {
        return t;
    } else if (key[0] == '\0') {
        t->finish = false;
    } else {
        int i = key[0] - 'a';
        t->children[i] = doTrieDelete(t->children[i], &key[1], false);
    }

    if (isRoot || t->finish) {
        return t;
    }

    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (t->children[i] != NULL) {
            return t;
        }
    }

    free(t);
    return NULL;
}

