    visited[v] = true
    numVerticesLeft = numVerticesLeft - 1
    if numVerticesLeft = 0:
        return true
    for each neighbour w of v in G:
        if visited[w] = false:
            if dfsHamiltonianPath(G, w, visited, numVerticesLeft):
                return true
    visited[v] = false
    return false

